/** Cây quyết định (thử nghiệm) — 1 đoạn mở đầu chung rồi rẽ nhánh theo phản hồi khác nhau, xem
 * `GrammarBranchingStory` trong `src/types/grammar.ts`. */
const KO_BRANCHING_STORIES: GrammarBranchingStory[] = [
  {
    id: "ko-branch-ru-di-choi",
    titleVn: "Rủ đi chơi",
    trunk: [
      { pointId: "ko-emo-neyo", exampleIndex: 0, timeLabelVn: "Nhận xét" },
      { pointId: "ko-qc-eulkkayo", exampleIndex: 0, timeLabelVn: "Rủ rê" },
    ],
    branches: [
      { labelVn: "Đồng ý", pointId: "ko-emo-go-sipda", exampleIndex: 2, timeLabelVn: "Đồng ý" },
      { labelVn: "Từ chối", pointId: "ko-tense-mot", exampleIndex: 1, timeLabelVn: "Từ chối" },
    ],
  },
];

const JA_BRANCHING_STORIES: GrammarBranchingStory[] = [
  {
    id: "ja-branch-ru-di-dao",
    titleVn: "Rủ đi dạo",
    trunk: [{ pointId: "ja-qc-mashou", exampleIndex: 0, timeLabelVn: "Rủ rê" }],
    branches: [
      { labelVn: "Đồng ý", pointId: "ja-emo-tai", exampleIndex: 2, timeLabelVn: "Đồng ý" },
      { labelVn: "Từ chối", pointId: "ja-conn-kara", exampleIndex: 1, timeLabelVn: "Từ chối" },
    ],
  },
];

const STATIC_STORIES: Partial<Record<Language, GrammarStory[]>> = { ko: KO_STORIES, ja: JA_STORIES };
const STATIC_BRANCHING_STORIES: Partial<Record<Language, GrammarBranchingStory[]>> = {
  ko: KO_BRANCHING_STORIES,
  ja: JA_BRANCHING_STORIES,
};

export function getGrammarStories(lang: string): GrammarStory[] {
  return STATIC_STORIES[lang as Language] ?? [];
}

export function getGrammarBranchingStories(lang: string): GrammarBranchingStory[] {
  return STATIC_BRANCHING_STORIES[lang as Language] ?? [];
}

export interface ResolvedGrammarStoryStep {
  timeLabelVn: string;
  point: GrammarPoint;
  example: GrammarExample;
}

export interface ResolvedGrammarStory {
  id: string;
  titleVn: string;
  steps: ResolvedGrammarStoryStep[];
}

export interface ResolvedGrammarBranch {
  labelVn: string;
  point: GrammarPoint;
  example: GrammarExample;
}

export interface ResolvedGrammarBranchingStory {
  id: string;
  titleVn: string;
  trunk: ResolvedGrammarStoryStep[];
  branches: ResolvedGrammarBranch[];
}

function findPoint(data: GrammarLanguageData, pointId: string): GrammarPoint | undefined {
  for (const category of data.categories) {
    const found = category.points.find((p) => p.id === pointId);
    if (found) return found;
  }
  return undefined;
}

function resolveStep(
  data: GrammarLanguageData,
  step: { pointId: string; exampleIndex: number; timeLabelVn: string },
): ResolvedGrammarStoryStep | null {
  const point = findPoint(data, step.pointId);
  const example = point?.examples[step.exampleIndex];
  if (!point || !example) return null;
  return { timeLabelVn: step.timeLabelVn, point, example };
}

/** Ghép mỗi `GrammarStoryStep` với `GrammarPoint`/`GrammarExample` thật của nó — bỏ qua bước nào
 * tham chiếu sai (không nên xảy ra nếu dữ liệu đúng, nhưng an toàn hơn là throw giữa chừng khi render). */
export function resolveStory(data: GrammarLanguageData, story: GrammarStory): ResolvedGrammarStory {
  const steps: ResolvedGrammarStoryStep[] = [];
  for (const step of story.steps) {
    const resolved = resolveStep(data, step);
    if (resolved) steps.push(resolved);
  }
  return { id: story.id, titleVn: story.titleVn, steps };
}

function resolveBranch(data: GrammarLanguageData, branch: GrammarBranchOption): ResolvedGrammarBranch | null {
  const point = findPoint(data, branch.pointId);
  const example = point?.examples[branch.exampleIndex];
  if (!point || !example) return null;
  return { labelVn: branch.labelVn, point, example };
}

export function resolveBranchingStory(
  data: GrammarLanguageData,
  story: GrammarBranchingStory,
): ResolvedGrammarBranchingStory {
  const trunk: ResolvedGrammarStoryStep[] = [];
  for (const step of story.trunk) {
    const resolved = resolveStep(data, step);
    if (resolved) trunk.push(resolved);
  }
  const branches: ResolvedGrammarBranch[] = [];
  for (const b of story.branches) {
    const resolved = resolveBranch(data, b);
    if (resolved) branches.push(resolved);
  }
  return { id: story.id, titleVn: story.titleVn, trunk, branches };
}
